 74	        if (candidate.isPersisted()) {
 75	          update(mapper, candidate, context, persistedAt);
 76	        } else {
 77	          mapper.insert(objects.forInsert(candidate, context.tenantId(), context.actor(), persistedAt));
 78	        }
 79	
 80	        StoreRow refreshed =
 81	            mapper.selectByTenantAndId(context.tenantId().value(), candidate.id().value());
 82	        if (refreshed == null) {
 83	          throw new StoreError("store.persistence-failure");
 84	        }
 85	        Store result = objects.toDomain(refreshed);
 86	        session.commit();
 87	        return result;
 88	      } catch (RuntimeException exception) {
 89	        session.rollback();
 90	        throw exception;
 91	      }
 92	    } catch (StoreError error) {
 93	      throw error;
 94	    } catch (PersistenceException exception) {
 95	      throw translated(exception);
 96	    } catch (RuntimeException exception) {
 97	      throw new StoreError("store.persistence-failure");
