101	  private void update(
102	      StoreRowMapper mapper,
103	      Store candidate,
104	      ExecutionContext context,
105	      Instant persistedAt) {
106	    StoreRow row =
107	        objects.forUpdate(candidate, context.tenantId(), context.actor(), persistedAt);
108	    if (mapper.updateByTenantIdAndVersion(row) != 1) {
