117	  private static StoreError translated(PersistenceException exception) {
118	    SQLException sql = findSqlException(exception);
119	    if (sql != null
120	        && sql.getErrorCode() == MYSQL_DUPLICATE_KEY
121	        && containsStoreCodeConstraint(sql.getMessage())) {
122	      return new StoreError("store.code-conflict");
