127	  private static SQLException findSqlException(Throwable failure) {
128	    Throwable current = failure;
129	    while (current != null) {
130	      if (current instanceof SQLException sql) {
131	        return sql;
132	      }
133	      current = current.getCause();
134	    }
135	    return null;
136	  }
